# Toy Merkle-Damgard hash (4-byte state) to show length-extension.
import struct
def compress(h, block):
    a, b, c, d = h
    m = struct.unpack('>4B', block)
    a = (a + m[0]) & 0xff
    b = ((b ^ m[1]) + a) & 0xff
    c = (c + m[2]) & 0xff
    d = ((d ^ m[3]) + c) & 0xff
    return (a, b, c, d)
def pad(m, total=None):
    ml = len(m) if total is None else total
    m = m + b'\x80'
    while (len(m) + 4) % 4 != 0:
        m += b'\x00'
    m += struct.pack('>I', ml)
    return m
def _blocks(h, m):
    for i in range(0, len(m), 4):
        h = compress(h, m[i:i+4])
    return h
def md(m):
    return _blocks((0x12, 0x34, 0x56, 0x78), pad(m))
def md_continue(h, suffix, total_before):
    body = suffix + b'\x80'
    while (len(body) + 4) % 4 != 0:
        body += b'\x00'
    body += struct.pack('>I', total_before + len(suffix))
    return _blocks(h, body)
